css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .2); display: flex; gap: 4%; }
.loader span { position: relative; flex: 1; overflow: hidden; background: color-mix(in srgb, #000 14%, var(--accent-2)); clip-path: polygon(50% 0, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%); }
.loader span::after { content: ''; position: absolute; top: 0; left: 0; width: 0; height: 100%; background: var(--accent); animation: rate calc(var(--loader-speed) * 2.6) ease-out infinite; }
.loader span:nth-child(2)::after { animation-delay: calc(var(--loader-speed) * .18); }
.loader span:nth-child(3)::after { animation-delay: calc(var(--loader-speed) * .36); }
.loader span:nth-child(4)::after { animation-delay: calc(var(--loader-speed) * .54); }
.loader span:nth-child(5)::after { animation-delay: calc(var(--loader-speed) * .72); }
@keyframes rate { 0% { width: 0; } 22% { width: 100%; } 82% { width: 100%; } 92%, 100% { width: 0; } }
